main.script:
(function () {
  'use strict';

  /* Pre-select the interest from ?interest=session|certification|event|listing|corporate|other */
  var map = { session: 'Individual or group session', certification: 'TRE Provider Certification', event: 'Event or workshop', listing: 'Directory listing', corporate: 'Corporate programme', other: 'Other enquiry' };
  var q = new URLSearchParams(window.location.search).get('interest');
  var pre = document.getElementById('f-interest');
  if (q && map[q] && pre) pre.value = map[q];

  /* Which channel suits which interest, as this page's own copy routes it:
     Email "certification questions, invoices and directory listings"; WhatsApp "event questions and same-week bookings";
     the discovery call "sessions, events or the certification pathway"; the form for listings and corporate
     programmes (the FAQ says to choose them in the form) and for anything else. */
  var ROUTES = {
    'Individual or group session': ['wa', 'call'],
    'TRE Provider Certification': ['email', 'call'],
    'Event or workshop': ['wa', 'call'],
    'Directory listing': ['email', 'form'],
    'Corporate programme': ['form'],
    'Other enquiry': ['form']
  };
  var EASE = 'cubic-bezier(.16,1,.3,1)';

  function $(s, c) { return (c || document).querySelector(s); }
  function $all(s, c) { return Array.prototype.slice.call((c || document).querySelectorAll(s)); }

  function init() {
    var L = window.TRELayer;
    var REDUCED = L ? L.reduced : !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
    var FINE = L ? L.fine : false;
    var IO = 'IntersectionObserver' in window;
    function visible(el, cb, opts) { if (L && L.onVisible) L.onVisible(el, cb, opts); else cb(null, true); }
    function watch(el, fn) { if ('ResizeObserver' in window) new ResizeObserver(function () { fn(); }).observe(el); else window.addEventListener('resize', fn); if (document.fonts && document.fonts.ready) document.fonts.ready.then(fn); }
    function belowFold(el) { return el.getBoundingClientRect().top > window.innerHeight * 0.92; }
    function flush(el) { return window.getComputedStyle(el).strokeDashoffset; }

    /* ---------- 1 · channel chooser ---------- */
    (function router() {
      var root = $('.ct-router'); if (!root) return;
      var svg = $('.ct-wires', root), answer = $('.ct-answer', root), chips = $all('.ct-chip', root), rows = {};
      $all('.ct-ch', root).forEach(function (r) { rows[r.getAttribute('data-ch')] = r; });
      var field = document.getElementById('f-interest'), byChooser = false, sel = null, hover = null;
      var wires = [], sig = '', entered = false, drawnIn = REDUCED;

      function targets(c) { return ROUTES[c.value] || []; }

      function build() {
        if (!svg || window.getComputedStyle(svg).display === 'none') { if (svg && wires.length) svg.innerHTML = ''; wires = []; sig = ''; return; }
        var box = root.getBoundingClientRect(), out = [];
        chips.forEach(function (c) {
          var a = c.getBoundingClientRect(), x1 = a.right - box.left + 4, y1 = a.top + a.height / 2 - box.top;
          targets(c).forEach(function (k) {
            var ring = rows[k] && $('.ct-ring', rows[k]); if (!ring) return;
            var b = ring.getBoundingClientRect(), x2 = b.left - box.left, y2 = b.top + b.height / 2 - box.top, dx = Math.max(24, (x2 - x1) * 0.55);
            out.push({ chip: c, key: k, d: 'M' + x1.toFixed(1) + ' ' + y1.toFixed(1) + ' C' + (x1 + dx).toFixed(1) + ' ' + y1.toFixed(1) + ' ' + (x2 - dx).toFixed(1) + ' ' + y2.toFixed(1) + ' ' + x2.toFixed(1) + ' ' + y2.toFixed(1) });
          });
        });
        var s = box.width.toFixed(0) + 'x' + box.height.toFixed(0) + out.map(function (w) { return w.d; }).join('');
        if (s === sig) return; sig = s;
        svg.setAttribute('viewBox', '0 0 ' + box.width.toFixed(1) + ' ' + box.height.toFixed(1));
        svg.innerHTML = out.map(function (w) { return '<path class="ct-w" d="' + w.d + '"/><path class="ct-w-hot" d="' + w.d + '"/>'; }).join('');
        var ps = $all('path', svg);
        wires = out.map(function (w, i) {
          w.base = ps[i * 2]; w.hot = ps[i * 2 + 1]; w.len = Math.ceil(w.hot.getTotalLength()) + 2; w.on = false;
          w.hot.style.strokeDasharray = w.len; w.hot.style.strokeDashoffset = w.len;
          if (!drawnIn) { w.base.style.strokeDasharray = w.len; w.base.style.strokeDashoffset = w.len; }
          return w;
        });
        if (entered && !drawnIn) drawIn();
        apply();
      }

      /* the wires draw themselves once, as the chooser comes into view */
      function drawIn() {
        if (!wires.length) return;
        drawnIn = true;
        var list = wires.slice();
        list.forEach(function (w) { flush(w.base); });
        requestAnimationFrame(function () {
          list.forEach(function (w, i) { w.base.style.transition = 'stroke-dashoffset 1.2s ' + EASE + ' ' + (i * 45) + 'ms, opacity .6s ' + EASE; w.base.style.strokeDashoffset = '0'; });
          setTimeout(function () { list.forEach(function (w) { w.base.style.transition = ''; w.base.style.strokeDasharray = ''; w.base.style.strokeDashoffset = ''; }); }, 1350 + list.length * 45);
        });
      }

      function apply() {
        var act = hover || (sel ? { chip: sel } : null), keys = [], lit = [];
        if (act && act.chip) { keys = targets(act.chip); lit = [act.chip]; }
        else if (act) { keys = [act.key]; lit = chips.filter(function (c) { return targets(c).indexOf(act.key) > -1; }); }
        Object.keys(rows).forEach(function (k) { rows[k].classList.toggle('is-match', keys.indexOf(k) > -1); });
        chips.forEach(function (c) { c.classList.toggle('is-hint', lit.indexOf(c) > -1 && c !== sel); });
        wires.forEach(function (w) {
          var on = !!act && (act.chip ? w.chip === act.chip : w.key === act.key);
          w.base.classList.toggle('dim', !!act && !on);
          if (on === w.on) return;
          w.on = on;
          if (on) {
            /* the route lights from the interest to the channel */
            w.hot.style.transition = 'none'; w.hot.style.strokeDashoffset = REDUCED ? '0' : String(w.len); flush(w.hot);
            w.hot.style.transition = ''; w.hot.style.strokeDashoffset = '0';
          }
          w.hot.classList.toggle('on', on);
        });
      }

      /* the answer, as direct links (shown under the chips on phones; spoken by screen readers everywhere) */
      function say() {
        if (!answer) return;
        answer.innerHTML = '';
        if (!sel) return;
        targets(sel).forEach(function (k) {
          var r = rows[k], link = r && $('.ct-ch-link a', r), name = r && $('h3', r); if (!link || !name) return;
          var a = document.createElement('a'); a.className = 'ct-go'; a.href = link.getAttribute('href');
          if (link.getAttribute('target')) { a.target = link.getAttribute('target'); a.rel = 'noopener'; }
          var ico = $('.ct-ico svg', r); if (ico) a.appendChild(ico.cloneNode(true));
          var t = document.createElement('span'); t.textContent = name.textContent; a.appendChild(t);
          answer.appendChild(a);
        });
      }

      function select(c, fromForm) {
        sel = c;
        chips.forEach(function (x) { x.setAttribute('aria-pressed', x === c ? 'true' : 'false'); });
        /* the form's interest follows the chooser, unless the visitor picked one in the form themselves */
        if (!fromForm && field) {
          if (c && (!field.value || byChooser)) { field.value = c.value; byChooser = true; field.dispatchEvent(new Event('change', { bubbles: true })); }
          else if (!c && byChooser) { field.value = ''; byChooser = false; field.dispatchEvent(new Event('change', { bubbles: true })); }
        }
        say(); apply();
      }

      chips.forEach(function (c) {
        c.addEventListener('click', function () { select(sel === c ? null : c); });
        c.addEventListener('pointerenter', function (e) { if (e.pointerType === 'mouse') { hover = { chip: c }; apply(); } });
        c.addEventListener('pointerleave', function () { if (hover && hover.chip === c) { hover = null; apply(); } });
        c.addEventListener('focus', function () { var kb = true; try { kb = c.matches(':focus-visible'); } catch (e) {} if (kb) { hover = { chip: c }; apply(); } });
        c.addEventListener('blur', function () { if (hover && hover.chip === c) { hover = null; apply(); } });
      });
      Object.keys(rows).forEach(function (k) {
        rows[k].addEventListener('pointerenter', function (e) { if (e.pointerType === 'mouse' && wires.length) { hover = { key: k }; apply(); } });
        rows[k].addEventListener('pointerleave', function () { if (hover && hover.key === k) { hover = null; apply(); } });
      });
      if (field) field.addEventListener('change', function (e) {
        if (!e.isTrusted) return;
        byChooser = false;
        select(chips.filter(function (x) { return x.value === field.value; })[0] || null, true);
      });
      /* when the form resets (after a send) the chooser lets go of its choice too */
      if (field && field.form) field.form.addEventListener('reset', function () { setTimeout(function () { if (sel && !field.value) { byChooser = false; select(null, true); } }, 0); });
      /* a pre-selected interest (?interest=…) shows as chosen */
      if (field && field.value) { var c0 = chips.filter(function (x) { return x.value === field.value; })[0]; if (c0) { byChooser = true; select(c0, true); } }

      build(); watch(root, build);
      visible(root, function (en, isIn) { if (isIn && !entered) { entered = true; if (!drawnIn) drawIn(); } }, { once: true, threshold: 0.2 });

      /* "Send a message" jumps to the form and (with a mouse) puts the cursor in the first field */
      document.addEventListener('click', function (e) {
        var a = e.target.closest ? e.target.closest('a[href="#contact-form"]') : null; if (!a || !FINE) return;
        setTimeout(function () { var n = document.getElementById('f-name'); if (n) { try { n.focus({ preventScroll: true }); } catch (x) { n.focus(); } } }, REDUCED ? 0 : 700);
      });
    })();

    /* ---------- 3 · the flow beside the form: ticks as the form is filled, advances when it is sent ---------- */
    (function flow() {
      var aside = $('.ct-after'), wrap = $('.ct-steps-wrap'), form = document.getElementById('contact-form'); if (!aside || !wrap || !form) return;
      var svg = $('.ct-steps-line', wrap), steps = $all('.ct-step', wrap), success = $('.form-success', form), sec = $('.ct-write');
      var sent = !!(success && success.classList.contains('show')), sig = '', armed = false, entered = false;

      function paint() {
        steps[0].classList.toggle('is-current', !sent); steps[0].classList.toggle('is-done', sent);
        if (steps[1]) steps[1].classList.toggle('is-current', sent);
        var s = $('.ct-seg', svg); if (s) s.classList.toggle('on', sent);
      }
      /* the line trembles a little by "You write" and has settled by the last step */
      function build() {
        var box = wrap.getBoundingClientRect(); if (!box.height || steps.length < 3) return;
        var P = steps.map(function (s) { var r = $('.ct-node', s).getBoundingClientRect(); return { x: r.left + r.width / 2 - box.left, y: r.top + r.height / 2 - box.top }; });
        var y0 = P[0].y, yN = P[P.length - 1].y, span = Math.max(1, yN - y0);
        function seg(a, b) {
          var d = '';
          for (var y = a; y < b + 3; y += 3) {
            var yy = Math.min(y, b), t = (yy - y0) / span, amp = 3.4 * Math.pow(1 - t, 2.2), x = P[0].x + amp * Math.sin((yy - y0) / 24 * 2 * Math.PI);
            d += (d ? ' L' : 'M') + x.toFixed(2) + ' ' + yy.toFixed(1);
          }
          return d;
        }
        var d1 = seg(y0, P[1].y), d2 = seg(P[1].y, yN), s = d1 + '|' + d2;
        if (s === sig) return; sig = s;
        svg.setAttribute('viewBox', '0 0 ' + box.width.toFixed(1) + ' ' + box.height.toFixed(1));
        svg.innerHTML = '<path class="ct-seg" d="' + d1 + '"/><path class="ct-seg" d="' + d2 + '"/>';
        wrap.classList.add('ct-drawn');
        if (armed && !entered) $all('.ct-seg', svg).forEach(function (p) { var len = Math.ceil(p.getTotalLength()) + 2; p.style.strokeDasharray = len; p.style.strokeDashoffset = len; });
        paint();
      }
      function drawLine() {
        var ps = $all('.ct-seg', svg);
        ps.forEach(function (p) { flush(p); });
        requestAnimationFrame(function () {
          ps.forEach(function (p, i) { p.style.transition = 'stroke-dashoffset .8s ' + EASE + ' ' + (260 + i * 440) + 'ms'; p.style.strokeDashoffset = '0'; });
          setTimeout(function () { ps.forEach(function (p) { p.style.transition = ''; p.style.strokeDasharray = ''; p.style.strokeDashoffset = ''; }); }, 1700);
        });
      }

      if (!REDUCED && IO && belowFold(aside)) {
        armed = true; aside.classList.add('ct-armed');
        visible(aside, function (en, isIn) { if (isIn && !entered) { entered = true; aside.classList.add('ct-in'); drawLine(); } }, { once: true, threshold: 0.25 });
      }
      build(); watch(wrap, build);

      if (success && 'MutationObserver' in window) new MutationObserver(function () {
        var s = success.classList.contains('show'); if (s !== sent) { sent = s; paint(); }
      }).observe(success, { attributes: true, attributeFilter: ['class'] });

      var ticks = $all('.ct-ticks [data-for]', wrap);
      function tick() {
        ticks.forEach(function (li) { var f = document.getElementById(li.getAttribute('data-for')); li.classList.toggle('ok', !!(f && f.value.trim() && f.checkValidity())); });
      }
      form.addEventListener('input', tick); form.addEventListener('change', tick);
      /* error styling appears after a send attempt; it clears when the form resets */
      form.addEventListener('submit', function () { if (sec) sec.classList.add('ct-tried'); });
      form.addEventListener('reset', function () { if (sec) sec.classList.remove('ct-tried'); setTimeout(function () { if (!success || !success.classList.contains('show')) tick(); }, 0); });
      tick(); paint();
    })();

    /* ---------- entrances for the quieter sections (only when they are still below the fold) ---------- */
    if (!REDUCED && IO) {
      $all('.ct-faq, .ct-find, .ct-close').forEach(function (s) {
        if (!belowFold(s)) return;
        s.classList.add('ct-armed');
        visible(s, function (en, isIn) { if (isIn) s.classList.add('ct-in'); }, { once: true, threshold: 0.15 });
      });
    }
  }

  document.addEventListener('DOMContentLoaded', function () { setTimeout(init, 0); });
})();
